{"check_build":{"code":"script({title:"Piplup — Iceberg Sentinel",description:"A towering blue Piplup stands chest-forward on a small cracked ice floe, with a white bib, bright beak, and webbed feet.",palette:{blue:"blue",belly:"white",gold:"bright light orange",ice:"trans light blue",black:"black",navy:"dark blue"}});
section("Ice Floe",[
 floor({at:[-15,0,-13],size:[30,20],layers:2,colour:"ice",top:"tile"}),
 place({part:"26074.dat",at:[-2,2,9],colour:"blue"}),
]);
section("Piplup",[
 cylinder({at:[-14,2,-14],diameter:28,height:36,colour:"blue"}),
 cylinder({at:[-11,29,-11],diameter:22,height:27,colour:"blue"}),
 // A tapered white bib follows the front of the chest in stepped, connected courses.
 ...[[-5,14],[-2,18],[1,20],[4,18],[7,14]].map(([y,w])=>wall({from:[-Math.floor(w/2),-15],to:[Math.floor(w/2)-1,-15],y:y+2,height:4,thickness:1,facing:"front",texture:"masonry",pattern:"courses",colour:"white"})),
 // Dark eye patches and a bright wedge-shaped beak make the face read at gallery distance.
 wall({from:[-6,-12],to:[-4,-12],y:43,height:6,thickness:1,facing:"front",colour:"black"}),
 wall({from:[4,-12],to:[6,-12],y:43,height:6,thickness:1,facing:"front",colour:"black"}),
 box({at:[-2,39,-15],size:[4,6,4],colour:"bright light orange",interior:"solid"}),
 // Wings project from either flank; their staggered sections give a down-swept flipper silhouette.
 wall({from:[-18,-2],to:[-13,1],y:13,height:15,thickness:2,facing:"front",colour:"blue"}),
 wall({from:[13,-2],to:[18,1],y:13,height:15,thickness:2,facing:"front",colour:"blue"}),
 // Two broad orange feet planted ahead of the body.
 box({at:[-10,2,-20],size:[8,5,9],colour:"bright light orange",interior:"solid"}),
 box({at:[2,2,-20],size:[8,5,9],colour:"bright light orange",interior:"solid"}),
 // Dark blue crown tuft and a raised tail visible from the back.
 place({part:"4460b.dat",at:[-1,54,-1],colour:"dark blue",turn:0}),
 place({part:"3001.dat",at:[-1,18,13],colour:"dark blue"}),
 place({part:"3001.dat",at:[1,18,13],colour:"dark blue"}),
]);","seed":1}}

